static void ck(cudaError_t e){if(e!=cudaSuccess)throw std::runtime_error(cudaGetErrorString(e));}
__host__ __device__ uint32_t val(uint32_t x){x^=0x9e3779b9u;x*=1664525u;return x+1013904223u;}
__global__ void initialize(uint32_t* a,uint32_t n){uint32_t i=blockIdx.x*blockDim.x+threadIdx.x;if(i<n)a[i]=val(i);}
__device__ uint32_t smid(){uint32_t s;asm("mov.u32 %0, %%smid;":"=r"(s));return s;}
__global__ void gather(const uint32_t* a,uint32_t n,const uint32_t* order,uint32_t* out,uint32_t* visit,uint32_t* sm,int reuse,int skew){uint32_t t=order[blockIdx.x];uint32_t group=reuse==0?t:reuse==1?t/8:0;uint32_t groups=reuse==0?256:reuse==1?32:1;uint32_t width=n/groups;int loops=(skew&&t%16==0)?128:16;uint32_t sum=0;if(threadIdx.x==0){sm[t*2]=smid();atomicAdd(visit+t,1u);}for(int j=0;j<loops;j++){uint32_t index=group*width+((t*131u+threadIdx.x*15485863u+j*32452843u)%width);sum+=a[index];}atomicAdd(out+t,sum);if(threadIdx.x==0)sm[t*2+1]=smid();}
__global__ void chain(const uint32_t* a,uint32_t n,uint32_t seed,uint32_t* out,uint64_t* cycles,uint32_t* sm,bool cg){if(threadIdx.x||blockIdx.x)return;uint32_t x=seed%n;sm[0]=smid();uint64_t start=clock64();for(int i=0;i<4096;i++){uint32_t y;if(cg)asm volatile("ld.global.cg.u32 %0, [%1];":"=r"(y):"l"(a+x):"memory");else y=a[x];x=y%n;}cycles[0]=clock64()-start;sm[1]=smid();out[0]=x;}
int main(int argc,char**argv){try{if(argc!=2)throw std::runtime_error("micro output directory");std::string dir=argv[1];cudaDeviceProp p;ck(cudaGetDeviceProperties(&p,0));size_t free,total;ck(cudaMemGetInfo(&free,&total));size_t bytes=size_t(p.l2CacheSize)*4;if(bytes+(2<<20)>std::min<size_t>(512ull<<20,free/10))throw std::runtime_error("diagnostic memory cap");uint32_t *a,*order,*out,*visits,*sm;uint64_t* cycles;ck(cudaMalloc(&a,bytes));ck(cudaMalloc(&order,256*4));ck(cudaMalloc(&out,256*4));ck(cudaMalloc(&visits,256*4));ck(cudaMalloc(&sm,512*4));ck(cudaMalloc(&cycles,8));cudaEvent_t begin,end;ck(cudaEventCreate(&begin));ck(cudaEventCreate(&end));std::ofstream f(dir+"/gather.csv"),c(dir+"/chain.csv");f<<"working_set_bytes,reuse,skew,schedule,repeat,gpu_ms,errors,sm_unique,migrations\n";c<<"working_set_bytes,load,seed,cycles,sm_begin,sm_end,kernel_ms,correct\n";double factors[]={.25,.75,1.5,4};std::vector<uint32_t> ids(256),output(256),seen(256),sms(512),expected(256);int configs=0,failures=0;for(double factor:factors){uint32_t n=size_t(p.l2CacheSize*factor)/4;initialize<<<(n+255)/256,256>>>(a,n);ck(cudaDeviceSynchronize());for(int load=0;load<2;load++)for(int sample=0;sample<16;sample++){uint32_t seed=sample*2718281u;ck(cudaEventRecord(begin));chain<<<1,1>>>(a,n,seed,out,cycles,sm,load);ck(cudaEventRecord(end));ck(cudaEventSynchronize(end));float ms;ck(cudaEventElapsedTime(&ms,begin,end));uint32_t actual,pos[2],x=seed%n;uint64_t cyc;ck(cudaMemcpy(&actual,out,4,cudaMemcpyDeviceToHost));ck(cudaMemcpy(pos,sm,8,cudaMemcpyDeviceToHost));ck(cudaMemcpy(&cyc,cycles,8,cudaMemcpyDeviceToHost));for(int j=0;j<4096;j++)x=val(x)%n;bool ok=x==actual;failures+=!ok;c<<n*4ull<<','<<load<<','<<seed<<','<<cyc<<','<<pos[0]<<','<<pos[1]<<','<<ms<<','<<ok<<'\n';if(ms>20)throw std::runtime_error("chain kernel >20ms");}
for(int reuse=0;reuse<3;reuse++)for(int skew=0;skew<2;skew++){for(uint32_t t=0;t<256;t++){uint32_t group=reuse==0?t:reuse==1?t/8:0;uint32_t groups=reuse==0?256:reuse==1?32:1,width=n/groups;int loops=skew&&t%16==0?128:16;uint32_t sum=0;for(uint32_t lane=0;lane<128;lane++)for(int j=0;j<loops;j++){uint32_t idx=group*width+((t*131u+lane*15485863u+j*32452843u)%width);sum+=val(idx);}expected[t]=sum;}
for(int policy=0;policy<4;policy++){configs++;std::iota(ids.begin(),ids.end(),0u);if(policy==1)std::reverse(ids.begin(),ids.end());if(policy==2)std::stable_sort(ids.begin(),ids.end(),[&](uint32_t x,uint32_t y){return (skew&&x%16==0)>(skew&&y%16==0);});if(policy==3){std::mt19937 rng(5080);std::shuffle(ids.begin(),ids.end(),rng);}ck(cudaMemcpy(order,ids.data(),1024,cudaMemcpyHostToDevice));for(int rep=0;rep<3;rep++){ck(cudaMemset(out,0,1024));ck(cudaMemset(visits,0,1024));ck(cudaEventRecord(begin));gather<<<256,128>>>(a,n,order,out,visits,sm,reuse,skew);ck(cudaEventRecord(end));ck(cudaEventSynchronize(end));float ms;ck(cudaEventElapsedTime(&ms,begin,end));ck(cudaMemcpy(output.data(),out,1024,cudaMemcpyDeviceToHost));ck(cudaMemcpy(seen.data(),visits,1024,cudaMemcpyDeviceToHost));ck(cudaMemcpy(sms.data(),sm,2048,cudaMemcpyDeviceToHost));int errors=0,migrations=0;std::vector<uint32_t> unique;for(int t=0;t<256;t++){errors+=output[t]!=expected[t]||seen[t]!=1;migrations+=sms[t*2]!=sms[t*2+1];unique.push_back(sms[t*2]);}std::sort(unique.begin(),unique.end());int count=std::unique(unique.begin(),unique.end())-unique.begin();f<<n*4ull<<','<<reuse<<','<<skew<<','<<policy<<','<<rep<<','<<ms<<','<<errors<<','<<count<<','<<migrations<<'\n';failures+=errors;if(ms>20)throw std::runtime_error("gather >20ms");}}}}
std::printf("{\"configurations\":%d,\"gather_launches\":%d,\"chain_launches\":128,\"errors\":%d,\"allocation_bytes\":%zu,\"topology_control\":false}\n",configs,configs*3,failures,bytes+5136);ck(cudaFree(a));ck(cudaFree(order));ck(cudaFree(out));ck(cudaFree(visits));ck(cudaFree(sm));ck(cudaFree(cycles));return failures?1:0;}catch(std::exception&e){std::fprintf(stderr,"micro_error: %s\n",e.what());return 2;}}
